package com.stepstracker.android.data.run

import com.stepstracker.android.data.*
import kotlinx.coroutines.flow.*
import java.time.Instant
import java.util.UUID

class RunRepository(private val dao:RunDao,private val api:ApiClient,val deviceId:String) {
    val active=dao.observeActive();val history=dao.observeHistory()
    fun details(id:String)=dao.observeDetails(id)
    suspend fun start(startedAt:Long=System.currentTimeMillis()):RunSessionEntity { check(dao.active()==null){"A run is already active"};val value=RunSessionEntity(UUID.randomUUID().toString(),deviceId,"ACTIVE",startedAt);dao.putSession(value);runCatching { api.createRun(CreateRunRequest(value.id,deviceId,Instant.ofEpochMilli(startedAt).toString()));dao.markCreated(value.id) };return value }
    suspend fun pause(id:String) { val s=dao.session(id)?:return;if(s.status!="ACTIVE")return;val now=System.currentTimeMillis();dao.putPause(RunPauseEntity(UUID.randomUUID().toString(),id,now));dao.putSession(s.copy(status="PAUSED",activeDurationMillis=activeDuration(s,now),serverSynced=false,updatedAt=now));runCatching { sync(id) } }
    suspend fun resume(id:String) { val s=dao.session(id)?:return;if(s.status!="PAUSED")return;val now=System.currentTimeMillis();dao.pauses(id).lastOrNull { it.resumedAt==null }?.let { dao.resumePause(it.id,now) };dao.putSession(s.copy(status="ACTIVE",updatedAt=now,serverSynced=false));runCatching { sync(id) } }
    suspend fun finish(id:String) { val s=dao.session(id)?:return;val now=System.currentTimeMillis();if(s.status=="PAUSED")dao.pauses(id).lastOrNull { it.resumedAt==null }?.let { dao.resumePause(it.id,now) };val duration=if(s.status=="ACTIVE")activeDuration(s,now) else s.activeDurationMillis;val distance=dao.points(id).sumOf { it.distanceFromPreviousMeters };dao.putSession(s.copy(status="COMPLETED",endedAt=now,activeDurationMillis=duration,distanceMeters=distance,averageSpeedMps=RunMetricsCalculator.averageSpeed(distance,duration),averagePaceSecondsPerKm=RunMetricsCalculator.pace(distance,duration),serverSynced=false,updatedAt=now));runCatching { sync(id) } }
    suspend fun addLocation(id:String,at:Long,lat:Double,lon:Double,altitude:Double?,accuracy:Float,speed:Float?,bearing:Float?):Boolean { val s=dao.session(id)?:return false;if(s.status!="ACTIVE")return false;val points=dao.points(id);val last=points.lastOrNull();val resumedAt=dao.pauses(id).lastOrNull()?.resumedAt;val previous=last?.takeUnless { resumedAt!=null&&it.recordedAt<resumedAt };val (accepted,distance)=RunMetricsCalculator.accept(previous,at,lat,lon,accuracy);if(!accepted)return false;val seq=(last?.sequence?:-1)+1;dao.putPoint(RunPointEntity(id,seq,at,lat,lon,altitude,accuracy,speed?.takeIf{it<=12},bearing,distance));val total=s.distanceMeters+distance;val duration=activeDuration(s,at);dao.putSession(s.copy(activeDurationMillis=duration,distanceMeters=total,averageSpeedMps=RunMetricsCalculator.averageSpeed(total,duration),averagePaceSecondsPerKm=RunMetricsCalculator.pace(total,duration),updatedAt=at));return true }
    suspend fun syncAll()=dao.pendingSessions().forEach { runCatching { sync(it.id) } }
    suspend fun tick(id:String){val s=dao.session(id)?:return;if(s.status=="ACTIVE"){val now=System.currentTimeMillis();dao.updateActiveDuration(id,activeDuration(s,now),now)}}
    suspend fun sync(id:String) { var s=dao.session(id)?:return;if(!s.serverCreated){api.createRun(CreateRunRequest(s.id,s.deviceId,Instant.ofEpochMilli(s.startedAt).toString()));dao.markCreated(id);s=dao.session(id)!!};do { val points=dao.pendingPoints(id);val pauses=dao.pauses(id);if(points.isEmpty()&&s.status=="COMPLETED")break;val result=api.checkpointRun(id,RunCheckpointRequest(if(s.status=="COMPLETED")"ACTIVE" else s.status,s.activeDurationMillis,pauses.map { RunPauseDto(it.id,Instant.ofEpochMilli(it.pausedAt).toString(),it.resumedAt?.let { t->Instant.ofEpochMilli(t).toString() }) },points.map { RunPointDto(it.sequence,Instant.ofEpochMilli(it.recordedAt).toString(),it.latitude,it.longitude,it.altitudeMeters,it.accuracyMeters,it.speedMps,it.bearingDegrees) }));dao.markPointsSynced(id,result.lastAcceptedSequence);dao.markCheckpoint(id,result.lastAcceptedSequence) } while(points.size==250)
        s=dao.session(id)!!;if(s.status=="COMPLETED"){val last=dao.points(id).lastOrNull()?.sequence?:-1;val summary=api.completeRun(id,CompleteRunRequest(Instant.ofEpochMilli(s.endedAt!!).toString(),s.activeDurationMillis,last));dao.putSession(s.copy(distanceMeters=summary.distanceMeters,averageSpeedMps=summary.averageSpeedMps,averagePaceSecondsPerKm=summary.averagePaceSecondsPerKm,caloriesKcal=summary.caloriesKcal,syncedPointSequence=summary.lastPointSequence,serverSynced=true,serverCreated=true,updatedAt=System.currentTimeMillis()))} }
    suspend fun delete(id:String){val local=dao.session(id)?:return;if(local.serverCreated)api.deleteRun(id);dao.delete(id)}
    suspend fun refreshHistory(){api.runs().items.forEach { remote->val local=dao.session(remote.id);dao.putSession((local?:RunSessionEntity(remote.id,deviceId,remote.status,Instant.parse(remote.startedAt).toEpochMilli())).copy(status=remote.status,endedAt=remote.endedAt?.let{Instant.parse(it).toEpochMilli()},activeDurationMillis=remote.activeDurationMillis,distanceMeters=remote.distanceMeters,averageSpeedMps=remote.averageSpeedMps,averagePaceSecondsPerKm=remote.averagePaceSecondsPerKm,caloriesKcal=remote.caloriesKcal,syncedPointSequence=remote.lastPointSequence,serverCreated=true,serverSynced=true))} }
    suspend fun hydrate(id:String){val remote=api.run(id);val current=dao.session(id)?:return;dao.putSession(current.copy(status=remote.summary.status,endedAt=remote.summary.endedAt?.let{Instant.parse(it).toEpochMilli()},activeDurationMillis=remote.summary.activeDurationMillis,distanceMeters=remote.summary.distanceMeters,averageSpeedMps=remote.summary.averageSpeedMps,averagePaceSecondsPerKm=remote.summary.averagePaceSecondsPerKm,caloriesKcal=remote.summary.caloriesKcal,serverCreated=true,serverSynced=true));remote.points.forEach { dao.putPoint(RunPointEntity(id,it.sequence,Instant.parse(it.recordedAt).toEpochMilli(),it.latitude,it.longitude,it.altitudeMeters,it.accuracyMeters,it.speedMps,it.bearingDegrees,synced=true)) };remote.pauses.forEach { dao.putPause(RunPauseEntity(it.id,id,Instant.parse(it.pausedAt).toEpochMilli(),it.resumedAt?.let{v->Instant.parse(v).toEpochMilli()})) } }
    private suspend fun activeDuration(s:RunSessionEntity,now:Long):Long { val paused=dao.pauses(s.id).sumOf { (it.resumedAt?:now)-it.pausedAt };return (now-s.startedAt-paused).coerceAtLeast(0) }
}
